// Expansion terrain for the existing Forsaken dimension. The released core and the
// mutant Outer Reaches are generated by ForsakenGen before this extension is considered.
import { B, CHUNK, HEIGHT, LOG_ALONG_X, LOG_ALONG_Z, make } from "./blocks.js";
import { Noise, hash3, hashSeed, rng } from "./noise.js";
import { prepareFallen } from "./forsaken-fallen.js";
import { prepareFortress } from "./forsaken-fortress.js";
import { buildSanctuary, protectedGatewayChunks } from "./forsaken-gateway.js";

export const KINGDOM_LAYOUT = 1;
export const KINGDOM_EDGE = 384;
const OLD_EDGE = 128;
const ROAD_RADIUS = 177;
const ROAD_LEVEL = 35;
const idx = (x, y, z) => x + z * CHUNK + y * CHUNK * CHUNK;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const smooth = t => { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); };
const mix = (a, b, t) => a + (b - a) * t;
const angle = Math.PI / 3;
const chunkKey = (cx, cz) => cx + "," + cz;
const radial = (x, z) => Math.max(Math.abs(x + 0.5), Math.abs(z + 0.5));

export const KINGDOM_BIOMES = Object.freeze({
  woods: { name: "Hollow Woods", top: B.ASH_SOIL, rock: B.FORSAKEN_STONE, low: 36, relief: 6, haze: 0x694055 },
  wastelands: { name: "Crimson Wastelands", top: B.BLACKSTONE, rock: B.BASALT, low: 40, relief: 30, haze: 0x914049 },
  kingdom: { name: "Forgotten Kingdom", top: B.ASH_SOIL, rock: B.FORSAKEN_STONE, low: 35, relief: 4, haze: 0x784352 },
  caverns: { name: "Corruption Caverns", top: B.FORSAKEN_STONE, rock: B.BLACKSTONE, low: 42, relief: 10, haze: 0x513457 },
  shattered: { name: "Shattered Lands", top: B.OBSIDIAN, rock: B.DARKSLATE, low: 37, relief: 10, haze: 0x663c68 },
  vale: { name: "Forsaken Vale", top: B.BLACKSTONE, rock: B.DARKSLATE, low: 38, relief: 12, haze: 0x823441 }
});
const ids = Object.keys(KINGDOM_BIOMES);
const sites = {
  crypt: ["wastelands", -25, 20], bastion: ["kingdom", 25, -18],
  crater: ["wastelands", 31, -18], nest: ["caverns", -24, -16], shrine: ["shattered", 0, 0],
};

export function makeKingdomLayout(worldSeed, data = {}) {
  const seed = hashSeed(worldSeed) ^ 0x2d58f09e;
  const rand = rng(seed);
  const orient = Math.floor(rand() * 4) * Math.PI / 2;
  const anchors = {};
  for (const [i, id] of ids.entries()) {
    const a = orient + i * angle + (rand() - 0.5) * 0.09;
    const radius = id === "vale" ? 273 : id === "shattered" ? 258 : 237;
    anchors[id] = { x: Math.round(Math.cos(a) * radius), z: Math.round(Math.sin(a) * radius) };
  }
  const protectedChunks = protectedGatewayChunks(data);
  const legacy = [...protectedChunks].filter(k => {
    const [x, z] = k.split(",").map(Number);
    return Math.min(x, z) < -8 || Math.max(x, z) >= 8;
  }).sort();
  const lairs = Object.fromEntries(Object.entries(sites).map(([name, [biome, dx, dz]]) => [
    name, { biome, x: anchors[biome].x + dx, z: anchors[biome].z + dz }
  ]));
  const { x, z } = anchors.vale;
  const candidates = [[0, -151], [0, 154], [64, -151], [-64, 154]];
  const refuge = candidates.find(([x, z]) => {
    for (let cx = Math.floor((x - 16) / CHUNK); cx <= Math.floor((x + 16) / CHUNK); cx++) {
      for (let cz = Math.floor((z - 14) / CHUNK); cz <= Math.floor((z + 14) / CHUNK); cz++) {
        if (protectedChunks.has(chunkKey(cx, cz))) return false;
      }
    }
    return true;
  });
  const sanctuary = refuge ? { x: refuge[0], y: ROAD_LEVEL, z: refuge[1] } : null;
  return { version: KINGDOM_LAYOUT, seed, anchors, lairs, fortress: { x, z, level: 39, radius: 63 }, sanctuary, legacy };
}

export function prepareKingdom(gen, data, worldSeed) {
  data.kingdom ??= makeKingdomLayout(worldSeed, data);
  if (validKingdomLayout(data.kingdom, worldSeed)) {
    gen.kingdom = new KingdomTerrain(data.kingdom);
    prepareFallen(gen.kingdom, data);
    prepareFortress(gen.kingdom, data);
  }
}

export function validKingdomLayout(layout, worldSeed) {
  const site = (p, limit = KINGDOM_EDGE - 2) => !!p && Number.isInteger(p.x) && Math.abs(p.x) <= limit &&
    Number.isInteger(p.z) && Math.abs(p.z) <= limit;
  return layout?.version === KINGDOM_LAYOUT && layout.seed === (hashSeed(worldSeed) ^ 0x2d58f09e) &&
    ids.every(id => site(layout.anchors?.[id], KINGDOM_EDGE - 78)) &&
    Object.keys(sites).every(id => site(layout.lairs?.[id]) && layout.lairs[id].biome === sites[id][0]) &&
    site(layout.fortress, KINGDOM_EDGE - 78) && layout.fortress.radius === 63 && layout.fortress.level === 39 &&
    (layout.sanctuary === null || site(layout.sanctuary, KINGDOM_EDGE - 20) && layout.sanctuary.y === ROAD_LEVEL) &&
    Array.isArray(layout.legacy) && layout.legacy.every(k => typeof k === "string" && /^-?\d+,-?\d+$/.test(k));
}

export class KingdomTerrain {
  constructor(layout) {
    this.layout = layout;
    this.seed = layout.seed;
    this.noise = new Noise(this.seed);
    this.legacy = new Set(layout.legacy);
    this.biomes = ids.map(id => ({ id, ...KINGDOM_BIOMES[id], ...layout.anchors[id] }));
    this.fortress = layout.fortress;
    this.sanctuary = layout.sanctuary;
    const {x, z} = layout.anchors.shattered;
    const r = Math.hypot(x, z);
    this.islands = [[0, 0, 22], [-42, -22, 12], [45, -19, 15], [10, 57, 16], [-40, 35, 13]]
      .map(([across, out, size]) => [x + (out * x - across * z) / r, z + (out * z + across * x) / r, size]);
  }

  contains(cx, cz) {
    return (Math.min(cx, cz) < -8 || Math.max(cx, cz) >= 8) && !this.legacy.has(chunkKey(cx, cz));
  }

  sample(x, z) {
    const { noise } = this, radius = Math.hypot(x, z);
    const bend = noise.n2(x / 53, z / 53) * 15;
    let nearest = Infinity, total = 0, weighted = 0, biome = this.biomes[0];
    for (const b of this.biomes) {
      const d = Math.hypot(x - b.x, z - b.z);
      const influence = Math.max(0, 1 - d / 265) ** 5;
      if (d < nearest) { nearest = d; biome = b; }
      total += influence;
      weighted += (b.low + b.relief * (Math.abs(noise.n2(x / 58, z / 58)) * 0.77 + noise.n2(x / 20, z / 20) * 0.24)) * influence;
    }
    const edge = radial(x, z);
    const oldLevel = 34 + noise.n2(x / 40, z / 40) * 2;
    let top = mix(oldLevel, total ? weighted / total : oldLevel, smooth((edge - OLD_EDGE) / 27));
    if (biome.id === "vale") top += 12 * Math.max(0, noise.n2(x / 46, z / 46)) + Math.abs(noise.n2(x / 33, z / 33)) * 5;
    const fort = this.fortress;
    const fortBlend = biome.id === "vale" ? 1 - smooth((Math.max(Math.abs(x - fort.x), Math.abs(z - fort.z)) - fort.radius) / 17) : 0;
    top = mix(top, fort.level, fortBlend);
    const spoke = Math.abs(x * biome.z - z * biome.x) / Math.hypot(biome.x, biome.z);
    const ring = Math.abs(radius - ROAD_RADIUS - bend);
    const trail = Math.min(ring, spoke);
    const bridged = biome.id === "shattered" && this.islands.slice(1).some(([ix, iz]) => {
      const dx = ix - biome.x, dz = iz - biome.z, d2 = dx * dx + dz * dz;
      const projection = clamp(((x - biome.x) * dx + (z - biome.z) * dz) / d2, 0, 1);
      return Math.hypot(x - biome.x - projection * dx, z - biome.z - projection * dz) < 2.5;
    });
    if (fortBlend < 1) top = mix(ROAD_LEVEL, top, Math.max(fortBlend, smooth((trail - 2) / 11)));
    const isRoad = trail <= 2.3 || bridged;
    let minY = 1;
    let isolated = false;
    if (biome.id === "shattered" && radius > ROAD_RADIUS + 18 && edge > OLD_EDGE + 19) {
      let land = -Infinity;
      for (const [ix, iz, size] of this.islands) land = Math.max(land, size - Math.hypot(x - ix, z - iz) + noise.n2(x / 7, z / 7) * 3);
      if (land < 0 && !isRoad) return { biome, top: -1, minY: -1, isRoad: false, isolated: true };
      isolated = true;
      top = isRoad ? ROAD_LEVEL : mix(ROAD_LEVEL, top, smooth(land / 12));
      minY = isRoad && land < 0 ? ROAD_LEVEL - 1 : Math.max(5, Math.round(top - 5 - Math.max(0, land) * 0.76));
    }
    return { biome, top: clamp(Math.round(top), 23, HEIGHT - 16), minY, isRoad, isolated, fortBlend };
  }

  column(x, z) {
    const col = this.sample(x, z);
    return { h: radial(x, z) >= KINGDOM_EDGE ? HEIGHT - 2 : col.top, biome: col.biome.id };
  }

  cavernRamp(x, z) {
    const center = this.layout.anchors.caverns, dz = z - center.z;
    if (Math.abs(x - center.x) > 2 || dz < -7 || dz > 45) return null;
    const surface = this.sample(x, center.z + 46).top;
    return Math.round(mix(14, surface, clamp((dz - 3) / 42, 0, 1)));
  }

  landmarks() {
    if (!this.detailSites) {
      const locate = (id, outward, sideways, kind) => {
        const { x, z } = this.layout.anchors[id], d = Math.hypot(x, z);
        const wx = Math.round(x + (x * outward - z * sideways) / d);
        const wz = Math.round(z + (z * outward + x * sideways) / d);
        return { x: wx, z: wz, y: this.column(wx, wz).h, kind };
      };
      this.detailSites = [
        locate("woods", -15, 14, "shelter"), locate("kingdom", -16, -13, "crossing"),
        locate("kingdom", -16, 14, "pasture"), locate("vale", -73, -34, "arch"),
        locate("shattered", 1, 0, "arch"),
      ];
    }
    return this.detailSites;
  }

  detailSite(site, put) {
    const { x, y, z, kind } = site;
    const set = (dx, h, dz, id) => put(x + dx, y + h, z + dz, id);
    if (kind === "arch") {
      for (const d of [-1, 1]) {
        for (let h = 0; h <= 7; h++) set(d * (h >= 6 ? 2 : 3), h, 0, h % 2 === 0 ? B.FORSAKEN_BRICKS : B.FORSAKEN_CRACKED);
        for (let h = 0; h < 4; h++) set(d * 4, h, 0, B.FORSAKEN_MOSSY);
        set(d * 4, 1, 1, B.VIOLET_CLUSTER);
      }
      for (let dx = -2; dx <= 2; dx++) if (dx !== -1) set(dx, 8, 0, B.FORSAKEN_CRACKED);
      return;
    }
    const half = kind === "shelter" ? 4 : 6;
    for (let dz = -half; dz <= half; dz++) for (let dx = -half; dx <= half; dx++) {
      const floor = this.column(x + dx, z + dz).h - y;
      for (let h = Math.min(floor, 0) - 1; h <= 0; h++) set(dx, h, dz, h === 0 && kind === "shelter" ? B.DEADWOOD_PLANKS : B.FORSAKEN_CRACKED);
      for (let h = 1; h <= Math.max(5, floor + 3); h++) set(dx, h, dz, B.AIR);
      const edge = Math.abs(dx) === half || Math.abs(dz) === half;
      const enter = dz === half && Math.abs(dx) <= 1;
      if (kind === "shelter") {
        if (edge && !enter) {
          const corner = Math.abs(dx) === half && Math.abs(dz) === half;
          for (let h = 1; h <= 4; h++) {
            const window = Math.abs(dx) === half && Math.abs(dz) < 2 && h === 2;
            set(dx, h, dz, window ? B.FORSAKEN_PANE : corner ? B.DEADWOOD_LOG : h === 1 ? B.FORSAKEN_MOSSY : B.DEADWOOD_PLANKS);
          }
        }
        if (!(dx > 1 && dz < -2)) set(dx, 4 + half - Math.abs(dx), dz, B.ROOF_TILES);
      } else if (edge && !enter) {
        const ruin = Math.floor(hash3(this.seed, x + dx, 197, z + dz) * (kind === "crossing" ? 5 : 2));
        for (let h = 1; h <= ruin; h++) set(dx, h, dz, h % 2 ? B.FORSAKEN_MOSSY : B.FORSAKEN_CRACKED);
      } else if (kind === "pasture" && Math.abs(dx) % 2 === 0) {
        set(dx, 0, dz, B.ASH_SOIL);
        if (hash3(this.seed, x + dx, 127, z + dz) > 0.65) set(dx, 1, dz, B.DEAD_BUSH);
      }
    }
    if (kind === "shelter") {
      set(-2, 1, -2, B.TABLE);
      set(-2, 1, -1, B.LANTERN);
      set(2, 1, -2, B.BARREL);
      set(-3, 1, 4, B.FORSAKEN_STAIRS);
      set(3, 1, 4, B.FORSAKEN_STAIRS);
      set(0, 0, 5, B.FORSAKEN_SLAB);
      set(0, 0, 6, B.FORSAKEN_BRICKS);
    }
    if (kind === "crossing") {
      for (const d of [-1, 1]) {
        for (let h = 1; h <= 4; h++) set(d * 3, h, -2, B.FORSAKEN_BRICKS);
        set(d * 3, 2, -1, B.FORSAKEN_BANNER);
        set(d * 4, 1, 0, B.LANTERN);
      }
      for (let dx = -2; dx <= 2; dx++) if (dx !== -1) set(dx, 5, -2, B.FORSAKEN_CRACKED);
    }
  }

  generate(cx, cz) {
    const data = new Uint32Array(CHUNK * CHUNK * HEIGHT);
    const x0 = cx * CHUNK, z0 = cz * CHUNK;
    const put = (x, y, z, v) => {
      if (x >= 0 && x < CHUNK && z >= 0 && z < CHUNK && y >= 0 && y < HEIGHT - 1) data[idx(x, y, z)] = v;
    };
    if (x0 < -KINGDOM_EDGE || z0 < -KINGDOM_EDGE || x0 >= KINGDOM_EDGE || z0 >= KINGDOM_EDGE) {
      data.fill(B.BEDROCK, 0, idx(0, HEIGHT - 1, 0));
      return data;
    }
    const { x: caveX, z: caveZ } = this.layout.anchors.caverns;
    const plants = [], falls = [];
    const structures = this.landmarks();
    for (let lz = 0; lz < CHUNK; lz++) for (let lx = 0; lx < CHUNK; lx++) {
      const x = x0 + lx, z = z0 + lz;
      const col = this.sample(x, z);
      const { biome, isRoad, isolated, minY, fortBlend } = col;
      if (col.top < 0) continue;
      let top = col.top;
      const refuge = this.sanctuary;
      const refugeDistance = refuge ? Math.max(Math.abs(x - refuge.x) - 12, Math.abs(z - refuge.z) - 10) : Infinity;
      if (refugeDistance < 8) top = Math.round(mix(refuge.y, top, smooth(refugeDistance / 7)));
      const rough = hash3(this.seed, x, 11, z), plant = hash3(this.seed, x, 55, z);
      const interior = radial(x, z) > OLD_EDGE + 12;
      const dx = x - caveX, dz = z - caveZ;
      const d = Math.hypot(dx, dz);
      const rampFloor = interior && biome.id === "caverns" ? this.cavernRamp(x, z) : null;
      const ramp = rampFloor !== null;
      const sink = interior && biome.id === "caverns" && d < 8 + this.noise.n2(x / 6, z / 6) * 2;
      const gallery = interior && biome.id === "caverns" && d < 33 + this.noise.n2(x / 9, z / 9) * 5;
      const floor = 13 + Math.round(this.noise.n2(x / 15, z / 15) * 2);
      if (ramp) top = rampFloor;
      else if (sink) top = Math.min(top, 17 + Math.floor(d * 0.4));
      const fissure = !isRoad && interior && biome.id === "wastelands" &&
        Math.abs(this.noise.n2(x / 27, z / 27)) < 0.045 && this.noise.n2(x / 62, z / 62) > 0.17;
      if (!isolated) put(lx, 0, lz, B.BEDROCK);
      for (let y = minY; y <= top; y++) {
        let rock = biome.rock;
        if (fissure && y > top - 4) rock = y === top - 3 ? B.LAVA : B.AIR;
        else if (!ramp && !sink && gallery && y > floor && y < Math.min(top - 4, 28 - Math.floor(d / 5))) rock = B.AIR;
        else if (ramp && y === top) rock = B.STONE_BRICKS;
        else if (gallery && y === floor && rough < 0.09) rock = B.FORSAKEN_RUNE;
        else if (y === top) rock = isRoad ? (rough < 0.36 ? B.CRACKED_BRICKS : B.COBBLE) : rough < 0.19 ? biome.rock : biome.top;
        else if (y > top - 4 && rough < 0.27) rock = B.BLACKSTONE;
        if (y === top - 1 && (biome.id === "wastelands" || biome.id === "caverns") && rough > 0.979) {
          rock = biome.id === "wastelands" ? B.SCARLET_ORE : B.VIOLET_ORE;
        }
        put(lx, y, lz, rock);
      }
      if (gallery && !ramp && !sink && !isRoad && data[idx(lx, floor + 1, lz)] === B.AIR && rough > 0.78) {
        put(lx, floor + 1, lz, B.VIOLET_CLUSTER);
        if (rough > 0.93) put(lx, floor + 2, lz, B.VIOLET_CLUSTER);
      }
      if (isolated && !isRoad && rough > 0.994) {
        const edge = [[0, 1], [-1, 0], [0, -1], [1, 0]].find(([dx, dz]) =>
          lx + dx >= 0 && lx + dx < CHUNK && lz + dz >= 0 && lz + dz < CHUNK && this.sample(x + dx, z + dz).top < 0);
        if (edge) falls.push([lx + edge[0], lz + edge[1], 3 + Math.floor(plant * 8), top]);
      }
      if (isRoad && isolated && minY >= ROAD_LEVEL - 1 && top === ROAD_LEVEL && rough > 0.86) {
        const xEdge = this.sample(x - 1, z).top < 0 || this.sample(x + 1, z).top < 0;
        const zEdge = this.sample(x, z - 1).top < 0 || this.sample(x, z + 1).top < 0;
        if (xEdge || zEdge) {
          put(lx, top + 1, lz, B.FORSAKEN_WALL);
          if (rough > 0.96) put(lx, top + 2, lz, B.LANTERN);
        }
      }
      if (isRoad || !interior || ramp || sink || fissure || fortBlend > 0.75 || refugeDistance < 4) continue;
      if (plant < (biome.id === "woods" ? 0.18 : 0.06)) {
        const decor = biome.id === "woods" ? (rough < 0.27 ? B.RED_MUSHROOM : B.CRIMSON_BRIAR)
          : rough < 0.35 ? (biome.id === "wastelands" ? B.SCARLET_CLUSTER : B.VIOLET_CLUSTER) : B.DEAD_BUSH;
        put(lx, top + 1, lz, decor);
      }
      if (biome.id === "wastelands" && plant > 0.966 && rough < 0.73) {
        const n = 2 + Math.round(rough * 4);
        for (let h = 1; h <= n; h++) put(lx, top + h, lz, B.BASALT);
        if (plant > 0.994) put(lx, top + n + 1, lz, B.SCARLET_CLUSTER);
      }
      if (lx > 2 && lx < CHUNK - 3 && lz > 2 && lz < CHUNK - 3 &&
          plant > (biome.id === "woods" ? 0.955 : biome.id === "vale" ? 0.984 : 1)) plants.push([lx, top, lz, rough, biome.id]);
    }
    for (const [x, z, bottom, top] of falls) for (let y = bottom; y < top; y++) put(x, y, z, B.VIOLET_FALL);
    for (const [lx, top, lz, rough, biome] of plants) {
      const height = 5 + Math.floor(rough * 5);
      const dx = rough > 0.5 ? 1 : -1, dz = rough > 0.5 ? -1 : 1;
      for (let dy = 1; dy <= height; dy++) put(lx, top + dy, lz, B.DEADWOOD_LOG);
      put(lx + dx, top + 1, lz, B.DEADWOOD_LOG);
      for (let i = 1; i <= 3; i++) {
        put(lx + dx * i, top + height - 3, lz, make(B.DEADWOOD_LOG, LOG_ALONG_X));
        put(lx, top + height - 1, lz + dz * i, make(B.DEADWOOD_LOG, LOG_ALONG_Z));
      }
      put(lx + dx * 3, top + height - 2, lz, B.DEADWOOD_LOG);
      put(lx, top + height, lz + dz * 3, B.DEADWOOD_LOG);
      if (rough > 0.44) {
        put(lx - dx, top + height - 1, lz + 1, B.DEADWOOD_LOG);
        put(lx - dx * 2, top + height, lz + 1, B.DEADWOOD_LOG);
      }
      if (biome === "vale" || rough < 0.3) {
        put(lx + dx * 2, top + height - 2, lz, B.CRIMSON_WART);
        put(lx, top + height + 1, lz + dz * 2, B.CRIMSON_WART);
      } else put(lx + dx * 2, top + height - 4, lz, B.VINES);
    }
    for (const site of structures) if (x0 <= site.x + 9 && x0 + CHUNK > site.x - 9 && z0 <= site.z + 9 && z0 + CHUNK > site.z - 9) {
      this.detailSite(site, (x, y, z, v) => put(x - x0, y, z - z0, v));
    }
    const r = this.sanctuary;
    if (r && x0 <= r.x + 12 && x0 + CHUNK > r.x - 12 && z0 <= r.z + 10 && z0 + CHUNK > r.z - 10) {
      buildSanctuary((x, y, z, v) => put(x - x0, y, z - z0, v), r);
    }
    return data;
  }
}
